const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([157.706220, -34.344553]);
  const region = point.buffer(100000); // 100km radius

  // Define comparison periods
  const period1_start = '2018-11-01';
  const period1_end = '2019-02-28';
  const period2_start = '2019-11-01';
  const period2_end = '2020-02-29';

  // 2. Data Acquisition - MERRA-2 for black carbon AOD
  const merra2_col = ee.ImageCollection('NASA/GSFC/MERRA/aer/2');

  const period1_col = merra2_col
    .filterDate(period1_start, period1_end)
    .filterBounds(region)
    .select('BCEXTTAU'); // Black carbon extinction aerosol optical depth

  const period2_col = merra2_col
    .filterDate(period2_start, period2_end)
    .filterBounds(region)
    .select('BCEXTTAU');

  // Check collection sizes
  const period1_size = period1_col.size().getInfo();
  const period2_size = period2_col.size().getInfo();

  console.log(`2018-19 Images: ${period1_size}`);
  console.log(`2019-20 Images: ${period2_size}`);

  if (period1_size === 0 || period2_size === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean black carbon AOD for each period
  const period1_mean = period1_col.mean();
  const period2_mean = period2_col.mean();

  // Get pixel counts and mean values
  const period1_stats = period1_mean.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 50000, // MERRA-2 resolution is ~50km
    maxPixels: 1e9
  });

  const period2_stats = period2_mean.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 50000,
    maxPixels: 1e9
  });

  const period1_mean_val = period1_stats.get('BCEXTTAU_mean').getInfo();
  const period1_count = period1_stats.get('BCEXTTAU_count').getInfo();
  const period2_mean_val = period2_stats.get('BCEXTTAU_mean').getInfo();
  const period2_count = period2_stats.get('BCEXTTAU_count').getInfo();

  console.log(`2018-19 BC AOD: ${period1_mean_val?.toFixed(4)}, Pixels: ${period1_count}`);
  console.log(`2019-20 BC AOD: ${period2_mean_val?.toFixed(4)}, Pixels: ${period2_count}`);

  // 4. Validation & Final Answer
  if (period1_count === 0 || period2_count === 0) {
    console.log("<answer>C2</answer>");
  } else if (period1_mean_val === null || period2_mean_val === null || 
             isNaN(period1_mean_val) || isNaN(period2_mean_val)) {
    console.log("<answer>C3</answer>");
  } else if (period2_mean_val > period1_mean_val) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
